mapper.select:
SELECT po.id AS id, po.order_no AS orderNo, po.supplier_id AS supplierId, s.name AS supplierName, po.status AS status, po.create_by AS createBy, po.create_time AS createTime, po.submit_time AS submitTime, po.audit_by AS auditBy, po.audit_time AS auditTime, po.expect_date AS expectDate, po.total_amount AS totalAmount, po.received_amount AS receivedAmount, po.return_amount AS returnAmount, COALESCE(stat.ordered_qty, 0) AS orderedQty, COALESCE(stat.received_qty, 0) AS receivedQty, CASE WHEN COALESCE(stat.ordered_qty, 0) = 0 THEN 0 ELSE CAST(ROUND(COALESCE(stat.received_qty, 0) / stat.ordered_qty * 100) AS SIGNED) END AS receiveProgress, po.settle_status AS settleStatus, po.settle_amount AS settleAmount, po.terminate_reason AS terminateReason, po.remark AS remark FROM purchase_order po JOIN supplier s ON s.id = po.supplier_id LEFT JOIN (SELECT order_id, SUM(quantity) AS ordered_qty, SUM(received_qty) AS received_qty FROM purchase_order_item GROUP BY order_id) stat ON stat.order_id = po.id
AND po.order_no LIKE CONCAT('%', #{q.orderNo}, '%')
AND po.supplier_id = #{q.supplierId}
AND po.status = #{q.status}
AND po.create_by LIKE CONCAT('%', #{q.createBy}, '%')
AND po.create_time >= #{beginTime}
AND po.create_time < #{endTime}
AND po.expect_date >= #{q.expectDateBegin}
AND po.expect_date <= #{q.expectDateEnd}
AND EXISTS (SELECT 1 FROM purchase_order_item poi JOIN goods g ON g.id = poi.goods_id WHERE poi.order_id = po.id AND (g.name LIKE CONCAT('%', #{q.goodsKeyword}, '%') OR g.goods_code LIKE CONCAT('%', #{q.goodsKeyword}, '%')))
ORDER BY po.id DESC

mapper.update:
UPDATE purchase_order_item
SET received_qty = received_qty + #{qty}
WHERE id = #{id}

UPDATE purchase_order_item
SET returned_qty = returned_qty + #{qty}
WHERE id = #{id}

UPDATE purchase_order_item
SET returned_qty = returned_qty + #{qty}
WHERE id = #{id}
  AND received_qty - returned_qty >= #{qty}

UPDATE purchase_order
SET received_amount = received_amount + #{amount},
    status          = #{status},
    version         = version + 1,
    update_by       = #{updateBy}
WHERE id = #{id}
  AND version = #{version}

UPDATE purchase_order
SET return_amount = return_amount + #{amount},
    status        = #{status},
    version       = version + 1,
    update_by     = #{updateBy}
WHERE id = #{id}
  AND version = #{version}
